    internal sealed class EngineeringAnalysisRecord
    {
        public string Id { get; set; }
        public string ArchitectureId { get; set; }
        public string CreatedUtc { get; set; }
        public string ArchitectureFingerprint { get; set; }
        public string CertificateHash { get; set; }
        public EngineeringRequirementAnalysis Requirements { get; set; }
        public EngineeringTopologyAnalysis Topology { get; set; }
        public List<EngineeringBudgetRow> Budgets { get; set; }
        public EngineeringScheduleAnalysis Schedule { get; set; }
        public EngineeringReliabilityAnalysis Reliability { get; set; }
        public List<EngineeringTradeEvaluation> Trades { get; set; }
        public EngineeringRiskEnvelope Risk { get; set; }
        public EngineeringSafetyCaseAnalysis SafetyCase { get; set; }
        public List<string> Audit { get; set; }
        public EngineeringAnalysisRecord() { Budgets = new List<EngineeringBudgetRow>(); Trades = new List<EngineeringTradeEvaluation>(); Audit = new List<string>(); }
        public override string ToString() { return (CreatedUtc ?? "") + "   ·   " + (Requirements == null ? "REQ —" : Requirements.AllocationCoverage.ToString("P0", CultureInfo.InvariantCulture) + " allocated") + "   ·   " + (Schedule == null ? "CPM —" : Schedule.ExpectedProjectDuration.ToString("0.##", CultureInfo.InvariantCulture) + " duration") + "   ·   " + (Reliability == null ? "R —" : "R=" + Reliability.SeriesReliability.ToString("0.000000", CultureInfo.InvariantCulture)) + "   ·   cert " + ShortHash(CertificateHash); }
        private static string ShortHash(string value) { return String.IsNullOrWhiteSpace(value) ? "∅" : value.Substring(0, Math.Min(16, value.Length)); }
    }

