        public static void Open(Window owner, DeepSystemsContext ctx) { if (ctx == null) return; Load(ctx); OpenHub(owner, ctx, WorldKernel.ExternalIndex(ctx, false)); }

        public static void OpenFromWorldNode(Window owner, DeepSystemsContext ctx, WorldIndex index, string nodeId)
        {
            if (ctx == null || index == null || String.IsNullOrWhiteSpace(nodeId)) return; WorldNode node; if (!index.Nodes.TryGetValue(nodeId, out node)) { Open(owner, ctx); return; } Load(ctx); string fingerprint = HashText((node.Id ?? "") + "|" + (node.Kind ?? "") + "|" + (node.Label ?? "") + "|" + (node.Fingerprint ?? "")); OpenProjection(owner, ctx, index, "WORLD", node.Id, fingerprint, delegate { EngineeringArchitecture a = StarterArchitecture("Engineer · " + (node.Label ?? node.Kind), "A bounded systems architecture projected from a World Kernel passport. Identity and provenance remain source evidence; projection creates no runtime authority."); a.EvidenceNodeIds.Add(node.Id); a.Requirements[0].Statement = "Preserve the source passport identity, provenance and declared boundary through engineering transformations."; a.Components[0].Name = node.Label ?? node.Kind ?? "Source object"; a.Components[0].EvidenceNodeIds.Add(node.Id); return a; });
        }

        public static void OpenFromCivilResolution(Window owner, DeepSystemsContext ctx, WorldIndex index, CivilResolution resolution)
        {
            if (ctx == null || resolution == null) return; Load(ctx); WorldIndex target = index ?? WorldKernel.ExternalIndex(ctx, false); string fingerprint = HashText((resolution.Id ?? "") + "|" + (resolution.Title ?? "") + "|" + (resolution.Proposition ?? "") + "|" + (resolution.Status ?? "") + "|" + String.Join("|", (resolution.EvidenceNodeIds ?? new List<string>()).OrderBy(x => x).ToArray())); OpenProjection(owner, ctx, target, "CIVILIZATION", resolution.Id, fingerprint, delegate { EngineeringArchitecture a = StarterArchitecture("Institutional system · " + (resolution.Title ?? "Resolution"), "Systems-engineering projection of a civil resolution. Deliberative adoption becomes a stakeholder source, never automatic technical feasibility or deployment authority."); a.Requirements[0].Name = "Resolution intent"; a.Requirements[0].Statement = resolution.Proposition ?? "Preserve the adopted stakeholder intent."; a.Requirements[0].EvidenceNodeIds.AddRange(resolution.EvidenceNodeIds ?? new List<string>()); a.EvidenceNodeIds.AddRange(resolution.EvidenceNodeIds ?? new List<string>()); return a; });
        }

        public static void OpenFromLogicTheory(Window owner, DeepSystemsContext ctx, WorldIndex index, LogicTheory theory)
        {
            if (ctx == null || theory == null) return; Load(ctx); WorldIndex target = index ?? WorldKernel.ExternalIndex(ctx, false); Dictionary<string, string> truth = EpistemicLogicFoundry.ExternalTheoryTruth(ctx, theory); string fingerprint = HashText((theory.Id ?? "") + "|" + (theory.Name ?? "") + "|" + (theory.Status ?? "") + "|" + String.Join("|", truth.OrderBy(x => x.Key).Select(x => x.Key + "=" + x.Value).ToArray())); OpenProjection(owner, ctx, target, "LOGIC", theory.Id, fingerprint, delegate { EngineeringArchitecture a = StarterArchitecture("Reasoning architecture · " + (theory.Name ?? "Theory"), "Engineering projection of a frozen paraconsistent theory. Proof states become requirements and assumptions only through an explicit translation boundary."); a.Assumptions.Add("Frozen theory spectrum: " + String.Join(", ", truth.Select(x => x.Key + "=" + x.Value).Take(32).ToArray())); foreach (KeyValuePair<string, string> q in truth.Take(64)) a.Requirements.Add(new EngineeringRequirement { Id = Id("requirement"), Name = "Theory question · " + Short(q.Key, 120), Statement = "Preserve explicit handling of " + q.Key + " with source truth state " + q.Value + ".", Kind = "EPISTEMIC", Priority = "SHOULD", Status = "DRAFT", VerificationMethod = "ANALYSIS", SatisfiedByComponentIds = new List<string> { a.Components[1].Id } }); return a; });
        }

        public static void OpenFromVerificationModel(Window owner, DeepSystemsContext ctx, WorldIndex index, VerificationModel model)
        {
            if (ctx == null || model == null) return; Load(ctx); WorldIndex target = index ?? WorldKernel.ExternalIndex(ctx, false); string fingerprint = VerificationKernel.Fingerprint(model); OpenProjection(owner, ctx, target, "VERIFICATION", model.Id, fingerprint, delegate { EngineeringArchitecture a = StarterArchitecture("Assurance architecture · " + (model.Name ?? "Finite-state model"), "Engineering projection of a verified finite-state abstraction. The formal model constrains architecture and verification planning; it does not become a physical implementation."); a.Components[1].Name = "Protocol implementation boundary"; a.Components[2].Name = "State observer and assurance monitor"; a.Requirements.Add(new EngineeringRequirement { Id = Id("requirement"), Name = "Behavioral abstraction fidelity", Statement = "Preserve an auditable relationship between implementation behavior and the source finite-state model.", Kind = "VERIFICATION", Priority = "SHALL", Status = "DRAFT", VerificationMethod = "FORMAL_ANALYSIS", SatisfiedByComponentIds = new List<string> { a.Components[1].Id, a.Components[2].Id }, EvidenceNodeIds = new List<string>(model.EvidenceNodeIds ?? new List<string>()) }); a.Assumptions.Add(model.States.Count + " states / " + model.Transitions.Count + " transitions at projection fingerprint " + Short(fingerprint, 32)); a.EvidenceNodeIds.AddRange(model.EvidenceNodeIds ?? new List<string>()); return a; });
        }

