        private static void OpenProjection(Window owner, DeepSystemsContext ctx, WorldIndex index, string kind, string sourceId, string fingerprint, Func<EngineeringArchitecture> create)
        {
            EngineeringArchitecture existing = LatestProjection(kind, sourceId); if (existing != null && Eq(existing.SourceFingerprint, fingerprint)) { OpenArchitecture(owner, ctx, index, existing); return; } if (existing != null) { string action = Choose(owner, "ENGINEERING PROJECTION DRIFT", "The upstream source changed after its engineering abstraction. Preserve the historical configuration boundary or create a current projection?", new[] { "OPEN HISTORICAL ARCHITECTURE", "CREATE CURRENT PROJECTION" }, "OPEN HISTORICAL ARCHITECTURE"); if (action == "OPEN HISTORICAL ARCHITECTURE") { OpenArchitecture(owner, ctx, index, existing); return; } if (action != "CREATE CURRENT PROJECTION") return; } EngineeringArchitecture architecture = create(); architecture.SourceKind = kind; architecture.SourceId = sourceId; architecture.SourceFingerprint = fingerprint; Store.Architectures.Insert(0, architecture); TrimStore(); Save(ctx); AppendLedger(ctx, "PROJECTION_CREATED", architecture.Id, kind + " · " + sourceId, SystemsEngineeringKernel.Fingerprint(architecture), ""); OpenArchitecture(owner, ctx, index, architecture);
        }

