        private static string CensusLine() { return Store.Architectures.Count(x => Active(x.Status)).ToString(CultureInfo.InvariantCulture) + " active architectures · " + Store.Architectures.Sum(x => x.Requirements.Count).ToString(CultureInfo.InvariantCulture) + " requirements · " + Store.Architectures.Sum(x => x.Components.Count).ToString(CultureInfo.InvariantCulture) + " components · " + Store.Architectures.Sum(x => x.Interfaces.Count).ToString(CultureInfo.InvariantCulture) + " interfaces · " + Store.Analyses.Count.ToString(CultureInfo.InvariantCulture) + " analyses · " + Store.Baselines.Count.ToString(CultureInfo.InvariantCulture) + " baselines · " + Store.Changes.Count.ToString(CultureInfo.InvariantCulture) + " changes"; }

        private static EngineeringArchitecture NewArchitecture(string name, string charter) { return new EngineeringArchitecture { Id = Id("architecture"), Name = Short(name, 240), Charter = Short(charter, MaxLongText), Status = "CONCEPT", LifecyclePhase = "CONCEPT", CreatedUtc = Now(), UpdatedUtc = Now(), Revision = 1, MissionHours = 8760 }; }
        private static EngineeringArchitecture StarterArchitecture(string name, string charter)
        {
            EngineeringArchitecture a = NewArchitecture(name, charter); EngineeringComponent source = C("source", "Source / environment boundary", "BOUNDARY", 8, 10, 20, 5, 0.000001, 0.1), core = C("core", "Core system", "SUBSYSTEM", 4, 25, 50, 30, 0.00001, 0.05), output = C("output", "Output / stakeholder boundary", "BOUNDARY", 7, 8, 15, 3, 0.000002, 0.1); a.Components.AddRange(new[] { source, core, output }); a.Interfaces.Add(I("source-core", source, core, "INPUT CONTRACT", 100, 2)); a.Interfaces.Add(I("core-output", core, output, "OUTPUT CONTRACT", 80, 4)); EngineeringRequirement mission = new EngineeringRequirement { Id = Id("requirement"), Name = "Mission capability", Statement = "The architecture shall deliver its declared mission outcome within the bounded environment and interface contracts.", Kind = "FUNCTIONAL", Priority = "SHALL", Status = "DRAFT", VerificationMethod = "DEMONSTRATION", SatisfiedByComponentIds = new List<string> { core.Id, output.Id } }, capacity = new EngineeringRequirement { Id = Id("requirement"), Name = "Sustained capacity", Statement = "The core output path shall sustain at least the declared capacity.", Kind = "PERFORMANCE", Priority = "SHALL", Status = "DRAFT", MetricKey = "throughput", Operator = ">=", Threshold = 50, Unit = "units/hour", VerificationMethod = "TEST", SatisfiedByComponentIds = new List<string> { core.Id, output.Id } }, safety = new EngineeringRequirement { Id = Id("requirement"), Name = "Fail-safe boundary", Statement = "Single identified failures shall not produce an uncontrolled hazardous output.", Kind = "SAFETY", Priority = "SHALL", Status = "DRAFT", VerificationMethod = "ANALYSIS", SatisfiedByComponentIds = new List<string> { core.Id } }; a.Requirements.AddRange(new[] { mission, capacity, safety });
            EngineeringResourceBudget mass = new EngineeringResourceBudget { Id = Id("budget"), Name = "Mass budget", Unit = "kg", Status = "ACTIVE", Available = 60, RequiredReserve = 6, Hard = true }, power = new EngineeringResourceBudget { Id = Id("budget"), Name = "Power budget", Unit = "kW", Status = "ACTIVE", Available = 100, RequiredReserve = 15, Hard = true }, compute = new EngineeringResourceBudget { Id = Id("budget"), Name = "Compute budget", Unit = "TFLOP/s", Status = "ACTIVE", Available = 50, RequiredReserve = 5, Hard = true }; foreach (EngineeringComponent c in a.Components) { mass.Allocations[c.Id] = c.Mass; power.Allocations[c.Id] = c.Power; compute.Allocations[c.Id] = c.Compute; } a.Budgets.AddRange(new[] { mass, power, compute });
            EngineeringTask concept = Tsk("concept", "Requirements and concept freeze", 2, 3, 5), design = Tsk("design", "Detailed architecture and interface control", 5, 8, 14), build = Tsk("build", "Bounded implementation work package", 8, 13, 24), integrate = Tsk("integrate", "Integration and interface reconciliation", 4, 7, 14), verify = Tsk("verify", "Verification and acceptance evidence", 4, 8, 18); design.PredecessorTaskIds.Add(concept.Id); build.PredecessorTaskIds.Add(design.Id); integrate.PredecessorTaskIds.Add(build.Id); verify.PredecessorTaskIds.Add(integrate.Id); a.Tasks.AddRange(new[] { concept, design, build, integrate, verify });
            EngineeringFailureMode coreFailure = new EngineeringFailureMode { Id = Id("failure"), ComponentId = core.Id, Name = "Core function loss", Cause = "Unresolved internal fault", Effect = "Mission capability unavailable", Mitigation = "Fault isolation, graceful degradation and recovery path", Status = "OPEN", Severity = 9, Occurrence = 3, Detectability = 4, Probability = 0.01 }, interfaceFailure = new EngineeringFailureMode { Id = Id("failure"), ComponentId = output.Id, Name = "Output contract violation", Cause = "Schema, timing or capacity mismatch", Effect = "Incorrect or late stakeholder output", Mitigation = "Contract monitor and rejection boundary", Status = "OPEN", Severity = 8, Occurrence = 4, Detectability = 3, Probability = 0.02 }; a.FailureModes.AddRange(new[] { coreFailure, interfaceFailure }); EngineeringFaultGate top = new EngineeringFaultGate { Id = Id("gate"), Name = "Mission loss", Kind = "OR", Status = "ACTIVE", InputIds = new List<string> { coreFailure.Id, interfaceFailure.Id } }; a.FaultGates.Add(top); a.TopFaultGateId = top.Id;
            EngineeringCriterion costCriterion = new EngineeringCriterion { Id = Id("criterion"), Name = "Lifecycle cost", Direction = "MINIMIZE", Status = "ACTIVE", Weight = 0.30 }, reliabilityCriterion = new EngineeringCriterion { Id = Id("criterion"), Name = "Mission reliability", Direction = "MAXIMIZE", Status = "ACTIVE", Weight = 0.40, Hard = true, Threshold = 0.90 }, throughputCriterion = new EngineeringCriterion { Id = Id("criterion"), Name = "Sustained throughput", Direction = "MAXIMIZE", Status = "ACTIVE", Weight = 0.30, Hard = true, Threshold = 50 }; a.Criteria.AddRange(new[] { costCriterion, reliabilityCriterion, throughputCriterion }); EngineeringAlternative conservative = new EngineeringAlternative { Id = Id("alternative"), Name = "Conservative architecture", Description = "Lower technical novelty with bounded throughput.", Status = "CANDIDATE", SelectedComponentIds = a.Components.Select(x => x.Id).ToList() }, ambitious = new EngineeringAlternative { Id = Id("alternative"), Name = "High-capacity architecture", Description = "Higher capacity with higher lifecycle burden.", Status = "CANDIDATE", SelectedComponentIds = a.Components.Select(x => x.Id).ToList() }; conservative.Metrics[costCriterion.Id] = 100; conservative.Metrics[reliabilityCriterion.Id] = 0.96; conservative.Metrics[throughputCriterion.Id] = 70; ambitious.Metrics[costCriterion.Id] = 145; ambitious.Metrics[reliabilityCriterion.Id] = 0.92; ambitious.Metrics[throughputCriterion.Id] = 120; a.Alternatives.AddRange(new[] { conservative, ambitious });
            EngineeringVerificationLink link = new EngineeringVerificationLink { Id = Id("verification"), RequirementId = safety.Id, ArtifactKind = "SAFETY_ANALYSIS", ArtifactId = "planned", Status = "PLANNED", Method = "ANALYSIS" }; a.VerificationLinks.Add(link); EngineeringSafetyClaim goal = new EngineeringSafetyClaim { Id = Id("claim"), Kind = "GOAL", Status = "OPEN", Statement = "The system is acceptably safe within the declared operational boundary." }, strategy = new EngineeringSafetyClaim { Id = Id("claim"), ParentClaimId = goal.Id, Kind = "STRATEGY", Status = "OPEN", Statement = "Argue over identified failure modes, interface containment and accepted verification evidence." }, solution = new EngineeringSafetyClaim { Id = Id("claim"), ParentClaimId = strategy.Id, Kind = "SOLUTION", Status = "OPEN", Statement = "Planned safety analysis and accepted verification certificate.", VerificationLinkIds = new List<string> { link.Id } }; a.SafetyClaims.AddRange(new[] { goal, strategy, solution }); a.Assumptions.Add("Starter costs, rates, durations, capacities and trade metrics are editable engineering placeholders, not calibrated forecasts."); return a;
        }

        private static EngineeringArchitecture ProjectStrategy(StrategyModel model)
        {
            EngineeringArchitecture a = NewArchitecture("Engineer strategy · " + (model.Name ?? "Causal model"), "Systems architecture projected from a structural causal strategy model. Variables and mechanisms become candidate components/interfaces; causal coefficients do not become physical specifications without engineering translation."); Dictionary<string, EngineeringComponent> byVariable = new Dictionary<string, EngineeringComponent>(StringComparer.OrdinalIgnoreCase); foreach (StrategyVariable v in (model.Variables ?? new List<StrategyVariable>()).Where(x => Active(x.Status)).Take(256)) { EngineeringComponent c = C("strategy-" + v.Id, v.Name, Eq(v.Kind, "DECISION") ? "CONTROL" : (Eq(v.Kind, "OUTCOME") ? "OUTPUT" : "SUBSYSTEM"), 2, 0, 0, 0, 0, 0); c.Id = "strategy-" + v.Id; c.Attributes["baseline"] = v.Baseline; c.Attributes["minimum"] = v.Minimum; c.Attributes["maximum"] = v.Maximum; c.EvidenceNodeIds.AddRange(v.EvidenceNodeIds ?? new List<string>()); a.Components.Add(c); byVariable[v.Id] = c; }
            foreach (StrategyEdge e in (model.Edges ?? new List<StrategyEdge>()).Where(x => Active(x.Status)).Take(MaxInterfaces)) { EngineeringComponent from, to; if (!byVariable.TryGetValue(e.FromVariableId ?? "", out from) || !byVariable.TryGetValue(e.ToVariableId ?? "", out to)) continue; EngineeringInterface edge = I("strategy-" + e.Id, from, to, e.Name, Math.Abs(e.Coefficient), Math.Max(0, e.Lag)); edge.Id = "strategy-" + e.Id; edge.Protocol = e.Transform; edge.Contract = "Engineering translation of structural mechanism β=" + e.Coefficient.ToString("R", CultureInfo.InvariantCulture) + "; empirical and physical validity remain unresolved."; edge.EvidenceNodeIds.AddRange(e.EvidenceNodeIds ?? new List<string>()); a.Interfaces.Add(edge); }
            foreach (StrategyObjective o in (model.Objectives ?? new List<StrategyObjective>()).Where(x => Active(x.Status))) { EngineeringComponent c = byVariable.ContainsKey(o.VariableId ?? "") ? byVariable[o.VariableId] : null; a.Requirements.Add(new EngineeringRequirement { Id = Id("requirement"), Name = o.Name, Statement = "Engineer an architecture that can measure and pursue the declared objective within explicit trade and assurance boundaries.", Kind = "PERFORMANCE", Priority = "SHOULD", Status = "DRAFT", MetricKey = "strategy:" + o.Id, Operator = Eq(o.Direction, "MINIMIZE") ? "<=" : ">=", Threshold = o.Aspiration, VerificationMethod = "ANALYSIS", SatisfiedByComponentIds = c == null ? new List<string>() : new List<string> { c.Id } }); a.Criteria.Add(new EngineeringCriterion { Id = "strategy-criterion-" + o.Id, Name = o.Name, Direction = o.Direction, Status = "ACTIVE", Weight = o.Weight }); }
            foreach (StrategyConstraint c in (model.Constraints ?? new List<StrategyConstraint>()).Where(x => Active(x.Status))) { EngineeringComponent component = byVariable.ContainsKey(c.VariableId ?? "") ? byVariable[c.VariableId] : null; a.Requirements.Add(new EngineeringRequirement { Id = Id("requirement"), Name = c.Name, Statement = "Preserve the declared strategy constraint as an engineering requirement pending dimensional and empirical validation.", Kind = "CONSTRAINT", Priority = Eq(c.Severity, "HARD") ? "SHALL" : "SHOULD", Status = "DRAFT", MetricKey = "strategy-constraint:" + c.VariableId, Operator = c.Operator, Threshold = c.Threshold, VerificationMethod = "ANALYSIS", SatisfiedByComponentIds = component == null ? new List<string>() : new List<string> { component.Id } }); }
            foreach (StrategyPolicy p in (model.Policies ?? new List<StrategyPolicy>()).Where(x => Active(x.Status))) { EngineeringAlternative alt = new EngineeringAlternative { Id = "strategy-policy-" + p.Id, Name = p.Name, Description = p.Description, Status = "CANDIDATE", SelectedComponentIds = a.Components.Where(c => p.Interventions.Any(i => Eq("strategy-" + i.VariableId, c.Id))).Select(c => c.Id).ToList(), Assumptions = new List<string> { "Policy projection is a design alternative, not an implemented configuration." } }; foreach (EngineeringCriterion c in a.Criteria) alt.Metrics[c.Id] = 0; a.Alternatives.Add(alt); } a.Assumptions.AddRange(model.Assumptions ?? new List<string>()); a.Assumptions.Add("Projected from strategy fingerprint " + Short(CounterfactualStrategyKernel.Fingerprint(model), 32) + "; causal coefficients remain hypothesis inputs."); a.EvidenceNodeIds.AddRange(model.EvidenceNodeIds ?? new List<string>()); if (a.Components.Count == 0) return StarterArchitecture(a.Name, a.Charter); return a;
        }

        private static EngineeringArchitecture ProjectDiscovery(DiscoveryProtocol protocol)
        {
            EngineeringArchitecture a = StarterArchitecture("Engineer experiment · " + (protocol.Name ?? "Discovery protocol"), "Systems architecture projected from a preregistered discovery protocol. Factors, measurements, inference and provenance become engineering work packages; YOMI still executes no experiment or deployment."); a.Components[0].Name = "Factor assignment / environment boundary"; a.Components[1].Name = "Measurement and provenance subsystem"; a.Components[2].Name = "Inference and reporting boundary"; a.Requirements.Clear(); foreach (DiscoveryFactor f in (protocol.Factors ?? new List<DiscoveryFactor>()).Where(x => Active(x.Status)).Take(128)) a.Requirements.Add(new EngineeringRequirement { Id = Id("requirement"), Name = "Factor integrity · " + f.Name, Statement = (f.Controllable ? "Control" : "Observe") + " factor " + f.Name + " over [" + f.Minimum.ToString("R", CultureInfo.InvariantCulture) + ", " + f.Maximum.ToString("R", CultureInfo.InvariantCulture) + "] " + (f.Unit ?? "") + " without crossing the preregistered assignment boundary.", Kind = f.Controllable ? "CONTROL" : "MEASUREMENT", Priority = "SHALL", Status = "DRAFT", VerificationMethod = "INSPECTION", SatisfiedByComponentIds = new List<string> { a.Components[0].Id }, EvidenceNodeIds = new List<string>(f.EvidenceNodeIds ?? new List<string>()) }); foreach (DiscoveryOutcome o in (protocol.Outcomes ?? new List<DiscoveryOutcome>()).Where(x => Active(x.Status)).Take(128)) a.Requirements.Add(new EngineeringRequirement { Id = Id("requirement"), Name = "Measurement · " + o.Name, Statement = "Measure " + o.Name + " with declared scale " + o.Scale + ", unit " + o.Unit + " and noise model σ=" + o.NoiseSigma.ToString("R", CultureInfo.InvariantCulture) + ".", Kind = "MEASUREMENT", Priority = "SHALL", Status = "DRAFT", MetricKey = "measurement-noise:" + o.Id, Operator = "<=", Threshold = o.NoiseSigma, Unit = o.Unit, VerificationMethod = "CALIBRATION", SatisfiedByComponentIds = new List<string> { a.Components[1].Id }, EvidenceNodeIds = new List<string>(o.EvidenceNodeIds ?? new List<string>()) }); a.Requirements.Add(new EngineeringRequirement { Id = Id("requirement"), Name = "Preregistration integrity", Statement = "Preserve the frozen stopping, analysis, exclusion, randomization and blocking boundaries through acquisition and reporting.", Kind = "CONFIGURATION", Priority = "SHALL", Status = "DRAFT", VerificationMethod = "INSPECTION", SatisfiedByComponentIds = new List<string> { a.Components[1].Id, a.Components[2].Id } }); a.Assumptions.AddRange(protocol.Assumptions ?? new List<string>()); a.Assumptions.Add("Discovery protocol fingerprint " + Short(ExperimentalDesignKernel.ProtocolFingerprint(protocol), 32) + "; design synthesis is not observation evidence."); a.EvidenceNodeIds.AddRange(protocol.EvidenceNodeIds ?? new List<string>()); return a;
        }

        private static EngineeringComponent C(string prefix, string name, string kind, int trl, double mass, double power, double compute, double failure, double repair) { return new EngineeringComponent { Id = prefix + "-" + Guid.NewGuid().ToString("N").Substring(0, 8), Name = name, Kind = kind, Status = "ACTIVE", TechnologyReadinessLevel = trl, Mass = mass, Power = power, Compute = compute, Heat = power * 0.65, Capacity = 100, CostOptimistic = 10, CostMostLikely = 15, CostPessimistic = 25, FailureRatePerHour = failure, RepairRatePerHour = repair }; }
        private static EngineeringInterface I(string prefix, EngineeringComponent from, EngineeringComponent to, string name, double capacity, double latency) { return new EngineeringInterface { Id = prefix + "-" + Guid.NewGuid().ToString("N").Substring(0, 8), FromComponentId = from.Id, ToComponentId = to.Id, Name = name, Kind = "DATA", Status = "ACTIVE", Medium = "DECLARED", Protocol = "VERSIONED CONTRACT", Contract = "Inputs, outputs, units, error semantics, timing and compatibility shall be explicitly versioned.", Precondition = "Source state is valid and provenance is available.", Postcondition = "Destination either accepts a conforming payload or returns a bounded failure.", Capacity = capacity, Latency = latency, Availability = 0.999 }; }
        private static EngineeringTask Tsk(string prefix, string name, double optimistic, double likely, double pessimistic) { return new EngineeringTask { Id = prefix + "-" + Guid.NewGuid().ToString("N").Substring(0, 8), Name = name, Status = "PLANNED", OptimisticDuration = optimistic, MostLikelyDuration = likely, PessimisticDuration = pessimistic, Cost = likely * 10, ResourceDemand = 1 }; }

        private static void OpenArchitectures(Window owner, DeepSystemsContext ctx, WorldIndex index) { Window w = W(owner, "YOMI · ENGINEERING ARCHITECTURE REGISTRY", 1200, 800); DockPanel root = Shell("SYSTEM ARCHITECTURE REGISTRY", CensusLine()); WrapPanel tools = new WrapPanel(); tools.Children.Add(Btn("FORGE ARCHITECTURE", delegate { CreateArchitecturePrompt(w, ctx, index); })); DockPanel.SetDock(tools, Dock.Top); root.Children.Add(tools); ListBox list = List(); list.ItemsSource = Store.Architectures.OrderByDescending(x => x.UpdatedUtc ?? x.CreatedUtc).ToList(); list.MouseDoubleClick += delegate { EngineeringArchitecture a = list.SelectedItem as EngineeringArchitecture; if (a != null) OpenArchitecture(w, ctx, index, a); }; root.Children.Add(list); w.Content = root; w.Show(); }
        private static void CreateArchitecturePrompt(Window owner, DeepSystemsContext ctx, WorldIndex index) { string name = Prompt(owner, "FORGE ARCHITECTURE", "Architecture name", "Engineered system " + DateTime.Now.ToString("yyyy-MM-dd HHmm", CultureInfo.InvariantCulture)); if (String.IsNullOrWhiteSpace(name)) return; string charter = PromptLarge(owner, "SYSTEM CHARTER", "Mission, stakeholders, environment, lifecycle and non-goals", "A bounded system architecture with explicit requirements, interfaces, resources, risks, verification and configuration authority."); if (charter == null) return; EngineeringArchitecture a = StarterArchitecture(name, charter); Store.Architectures.Insert(0, a); TrimStore(); Save(ctx); AppendLedger(ctx, "ARCHITECTURE_FORGED", a.Id, a.Name, SystemsEngineeringKernel.Fingerprint(a), ""); OpenArchitecture(owner, ctx, index, a); }

        private static void OpenArchitecture(Window owner, DeepSystemsContext ctx, WorldIndex index, EngineeringArchitecture a)
