, delegate { FreezeBaseline(w, ctx, a); })); tools.Children.Add(Btn("PROPOSE CHANGE", delegate { ProposeChange(w, ctx, index, a); })); tools.Children.Add(Btn(Active(a.Status) ? "ARCHIVE" : "RESTORE", delegate { a.Status = Active(a.Status) ? "ARCHIVED" : "CONCEPT"; Touch(a); Save(ctx); AppendLedger(ctx, "ARCHITECTURE_" + a.Status, a.Id, a.Name, SystemsEngineeringKernel.Fingerprint(a), ""); w.Close(); })); tools.Children.Add(Btn("HADAL DESCENT", delegate { AbyssalKnowledgeEngine.DescendFromExternal(w, ctx, a.Name, a, StorePath(ctx), "$architectures:" + a.Id, "DYSON › ARCHITECTURE"); })); DockPanel.SetDock(tools, Dock.Top); root.Children.Add(tools); Grid body = new Grid(); body.ColumnDefinitions.Add(new ColumnDefinition()); body.ColumnDefinitions.Add(new ColumnDefinition()); body.ColumnDefinitions.Add(new ColumnDefinition()); ListBox requirements = List(); requirements.ItemsSource = a.Requirements; requirements.MouseDoubleClick += delegate { EngineeringRequirement q = requirements.SelectedItem as EngineeringRequirement; if (q != null) OpenRequirement(w, ctx, index, a, q); }; ListBox components = List(); components.ItemsSource = a.Components; components.MouseDoubleClick += delegate { EngineeringComponent c = components.SelectedItem as EngineeringComponent; if (c != null) OpenComponent(w, ctx, index, a, c); }; ListBox interfaces = List(); interfaces.ItemsSource = a.Interfaces; interfaces.MouseDoubleClick += delegate { EngineeringInterface i = interfaces.SelectedItem as EngineeringInterface; if (i != null) OpenInterface(w, ctx, index, a, i); }; Grid.SetColumn(requirements, 0); Grid.SetColumn(components, 1); Grid.SetColumn(interfaces, 2); body.Children.Add(requirements); body.Children.Add(components); body.Children.Add(interfaces); DockPanel.SetDock(body, Dock.Top); body.Height = 430; root.Children.Add(body); root.Children.Add(ReadOnly("SYSTEM CHARTER\r\n" + (a.Charter ?? "") + "\r\n\r\nASSUMPTIONS\r\n" + String.Join("\r\n", a.Assumptions.Select(x => "  • " + x).ToArray()) + "\r\n\r\nSOURCE\r\n" + (a.SourceKind ?? "OPERATOR") + " · " + (a.SourceId ?? "") + "\r\n" + (a.SourceFingerprint ?? ""))); w.Content = root; w.Show();
        }

        private static void AddRequirement(Window owner, DeepSystemsContext ctx, EngineeringArchitecture a) { if (a.Requirements.Count >= MaxRequirements) return; string name = Prompt(owner, "ADD REQUIREMENT", "Requirement name", "System requirement"); if (String.IsNullOrWhiteSpace(name)) return; string statement = PromptLarge(owner, "NORMATIVE STATEMENT", "Atomic, necessary, unambiguous, verifiable statement", "The system shall..."); if (statement == null) return; string kind = Choose(owner, "REQUIREMENT KIND", "Classification", new[] { "FUNCTIONAL", "PERFORMANCE", "INTERFACE", "RESOURCE", "SAFETY", "SECURITY", "RELIABILITY", "CONFIGURATION", "EPISTEMIC" }, "FUNCTIONAL"); if (kind == null) return; string priority = Choose(owner, "NORMATIVE PRIORITY", "Obligation level", new[] { "SHALL", "SHOULD", "MAY" }, "SHALL"); if (priority == null) return; string metric = Prompt(owner, "METRIC KEY", "Shared metric key for quantitative conflict analysis; blank for qualitative", ""); string op = String.IsNullOrWhiteSpace(metric) ? ">=" : Choose(owner, "BOUND OPERATOR", "Quantitative constraint", new[] { ">=", ">", "<=", "<", "==" }, ">="); double threshold = String.IsNullOrWhiteSpace(metric) ? 0 : Number(Prompt(owner, "THRESHOLD", "Quantitative boundary", "0"), 0); string method = Choose(owner, "VERIFICATION METHOD", "Planned acceptance method", new[] { "ANALYSIS", "INSPECTION", "TEST", "DEMONSTRATION", "FORMAL_ANALYSIS", "CALIBRATION" }, "ANALYSIS"); EngineeringRequirement q = new EngineeringRequirement { Id = Id("requirement"), Name = Short(name, 240), Statement = Short(statement, MaxLongText), Kind = kind, Priority = priority, Status = "DRAFT", MetricKey = Short(metric, 180), Operator = op, Threshold = threshold, Unit = Short(Prompt(owner, "UNIT", "Metric unit", ""), 80), Tolerance = Math.Max(0, Number(Prompt(owner, "TOLERANCE", "Conflict tolerance", "0"), 0)), VerificationMethod = method }; EngineeringComponent allocated = ChooseObject(owner, "INITIAL ALLOCATION", "Optional satisfying component", new object[] { "UNALLOCATED" }.Concat(a.Components.Cast<object>()).ToList()) as EngineeringComponent; if (allocated != null) q.SatisfiedByComponentIds.Add(allocated.Id); a.Requirements.Add(q); Touch(a); Save(ctx); AppendLedger(ctx, "REQUIREMENT_ADDED", q.Id, q.Name, SystemsEngineeringKernel.Fingerprint(a), ""); }
        private static void AddComponent(Window owner, DeepSystemsContext ctx, EngineeringArchitecture a) { if (a.Components.Count >= MaxComponents) return; string name = Prompt(owner, "ADD COMPONENT", "Component name", "New subsystem"); if (String.IsNullOrWhiteSpace(name)) return; string kind = Choose(owner, "COMPONENT KIND", "Architectural role", new[] { "SYSTEM", "SUBSYSTEM", "SERVICE", "CONTROL", "STORAGE", "COMPUTE", "ENERGY", "THERMAL", "STRUCTURE", "SENSOR", "ACTUATOR", "BOUNDARY" }, "SUBSYSTEM"); if (kind == null) return; int trl = (int)Math.Max(1, Math.Min(9, Number(Prompt(owner, "TECHNOLOGY READINESS", "TRL 1–9", "3"), 3))); EngineeringComponent c = new EngineeringComponent { Id = Id("component"), Name = Short(name, 240), Kind = kind, Status = "ACTIVE", Description = Short(PromptLarge(owner, "COMPONENT DESCRIPTION", "Responsibility, boundary and non-responsibilities", "Bounded architectural component."), MaxLongText), TechnologyReadinessLevel = trl, Mass = Math.Max(0, Number(Prompt(owner, "MASS", "Mass allocation", "0"), 0)), Power = Math.Max(0, Number(Prompt(owner, "POWER", "Power allocation", "0"), 0)), Compute = Math.Max(0, Number(Prompt(owner, "COMPUTE", "Compute allocation", "0"), 0)), Heat = Math.Max(0, Number(Prompt(owner, "HEAT", "Thermal rejection", "0"), 0)), Capacity = Math.Max(0, Number(Prompt(owner, "CAPACITY", "Nominal capacity", "0"), 0)), CostOptimistic = Math.Max(0, Number(Prompt(owner, "COST LOW", "Optimistic lifecycle cost", "0"), 0)), FailureRatePerHour = Math.Max(0, Number(Prompt(owner, "FAILURE RATE", "Failures per operating hour", "0"), 0)), RepairRatePerHour = Math.Max(0, Number(Prompt(owner, "REPAIR RATE", "Repairs per hour", "0"), 0)) }; c.CostMostLikely = Math.Max(c.CostOptimistic, Number(Prompt(owner, "COST LIKELY", "Most-likely lifecycle cost", c.CostOptimistic.ToString("R", CultureInfo.InvariantCulture)), c.CostOptimistic)); c.CostPessimistic = Math.Max(c.CostMostLikely, Number(Prompt(owner, "COST HIGH", "Pessimistic lifecycle cost", c.CostMostLikely.ToString("R", CultureInfo.InvariantCulture)), c.CostMostLikely)); a.Components.Add(c); Touch(a); Save(ctx); AppendLedger(ctx, "COMPONENT_ADDED", c.Id, c.Name, SystemsEngineeringKernel.Fingerprint(a), ""); }
