", delegate { OpenRows(w, "TRADE SPACE", r.Trades.Cast<object>().ToList(), "Pareto, weighted utility, TOPSIS, minimax regret and concordance outranking."); })); tools.Children.Add(Btn("RISK", delegate { OpenRows(w, "PROGRAM RISK ENVELOPE", new List<object> { r.Risk }.Concat(r.Risk.Audit.Cast<object>()).ToList(), r.Risk.Fingerprint); })); tools.Children.Add(Btn("SAFETY CASE", delegate { OpenRows(w, "SAFETY CASE", new List<object> { r.SafetyCase }.Concat(r.SafetyCase.Warnings.Cast<object>()).ToList(), "Coverage requires evidence-bound descendant solutions."); })); tools.Children.Add(Btn("CREATE DOSSIER", delegate { if (a != null) CreateDossier(w, ctx, index, a, r); })); tools.Children.Add(Btn("HADAL DESCENT", delegate { AbyssalKnowledgeEngine.DescendFromExternal(w, ctx, "Engineering analysis " + r.Id, r, StorePath(ctx), "$analyses:" + r.Id, "DYSON › ANALYSIS"); })); DockPanel.SetDock(tools, Dock.Top); root.Children.Add(tools); root.Children.Add(ReadOnly("STRUCTURAL AUDIT\r\n" + String.Join("\r\n", r.Audit.Select(x => "  " + x).ToArray()) + "\r\n\r\nARCHITECTURE FINGERPRINT\r\n" + r.ArchitectureFingerprint + "\r\n\r\nANALYSIS CERTIFICATE\r\n" + r.CertificateHash)); w.Content = root; w.Show(); }

