        private static void FreezeBaseline(Window owner, DeepSystemsContext ctx, EngineeringArchitecture a) { List<string> audit = SystemsEngineeringKernel.Audit(a); if (audit.Any(x => x.StartsWith("BLOCKER", StringComparison.OrdinalIgnoreCase))) { MessageBox.Show(owner, String.Join("\r\n", audit.ToArray()), "YOMI · Baseline Blocked"); return; } string architectureHash = SystemsEngineeringKernel.Fingerprint(a); EngineeringConfigurationBaseline latest = Store.Baselines.Where(x => Eq(x.ArchitectureId, a.Id)).OrderByDescending(x => x.FrozenUtc).FirstOrDefault(); string name = Prompt(owner, "CONFIGURATION BASELINE", "Baseline name", (a.LifecyclePhase ?? "CONCEPT") + " baseline r" + a.Revision); if (String.IsNullOrWhiteSpace(name)) return; string reason = latest == null ? "INITIAL CONFIGURATION FREEZE" : PromptLarge(owner, "REBASELINE REASON", "Explain the authorized configuration boundary change; historical baseline remains immutable", "Authorized engineering change and explicit rebaseline."); if (reason == null) return; string snapshot = Json.Serialize(a), baselineHash = HashText("ENGINEERING_BASELINE_V1|" + architectureHash + "|" + snapshot); if (latest != null && Eq(latest.BaselineFingerprint, baselineHash)) { MessageBox.Show(owner, "An identical frozen baseline already exists.\r\n\r\n" + baselineHash, "YOMI · Configuration Vault"); return; } EngineeringConfigurationBaseline b = new EngineeringConfigurationBaseline { Id = Id("baseline"), ArchitectureId = a.Id, ParentBaselineId = latest == null ? "" : latest.Id, Name = Short(name, 240), Status = latest == null ? "FROZEN" : "REBASELINED", FrozenUtc = Now(), Reason = Short(reason, MaxLongText), ArchitectureFingerprint = architectureHash, BaselineFingerprint = baselineHash, SnapshotJson = snapshot }; Store.Baselines.Insert(0, b); Save(ctx); AppendLedger(ctx, "BASELINE_FROZEN", b.Id, b.Name + " · " + reason, architectureHash, baselineHash); }
        private static void OpenBaselines(Window owner, DeepSystemsContext ctx) { Window w = W(owner, "YOMI · CONFIGURATION BASELINE VAULT", 1220, 800); DockPanel root = Shell("IMMUTABLE CONFIGURATION BASELINES", Store.Baselines.Count + " frozen architecture snapshots with parent-linked rebaseline lineage."); ListBox list = List(); list.ItemsSource = Store.Baselines.OrderByDescending(x => x.FrozenUtc).ToList(); list.MouseDoubleClick += delegate { EngineeringConfigurationBaseline b = list.SelectedItem as EngineeringConfigurationBaseline; if (b != null) OpenBaseline(w, b); }; root.Children.Add(list); w.Content = root; w.Show(); }
