        private static void ProposeChangeFromComponent(Window owner, DeepSystemsContext ctx, WorldIndex index, EngineeringArchitecture a, EngineeringComponent c) { string title = Prompt(owner, "ENGINEERING CHANGE", "Change title", "Change · " + c.Name); if (String.IsNullOrWhiteSpace(title)) return; string description = PromptLarge(owner, "CHANGE DESCRIPTION", "Proposed before/after technical boundary", "Describe the proposed change without mutating the current configuration."); if (description == null) return; List<string> impact = SystemsEngineeringKernel.Impact(a, c.Id); HashSet<string> impactedSet = new HashSet<string>(impact, StringComparer.OrdinalIgnoreCase); EngineeringChangeRecord change = new EngineeringChangeRecord { Id = Id("change"), ArchitectureId = a.Id, ComponentId = c.Id, Title = Short(title, 240), Description = Short(description, MaxLongText), Rationale = Short(PromptLarge(owner, "CHANGE RATIONALE", "Need, evidence, alternatives and urgency", "Bounded engineering rationale."), MaxLongText), Status = "PROPOSED", CreatedUtc = Now(), UpdatedUtc = Now(), BeforeFingerprint = SystemsEngineeringKernel.Fingerprint(a), ImpactedComponentIds = impact, ImpactedRequirementIds = a.Requirements.Where(q => (q.SatisfiedByComponentIds ?? new List<string>()).Any(impactedSet.Contains)).Select(q => q.Id).Distinct(StringComparer.OrdinalIgnoreCase).ToList(), EvidenceNodeIds = new List<string>(c.EvidenceNodeIds ?? new List<string>()) }; Store.Changes.Insert(0, change); Save(ctx); AppendLedger(ctx, "CHANGE_PROPOSED", change.Id, change.Title, change.BeforeFingerprint, ""); OpenChange(owner, ctx, index, change); }
