        private static void CreateDossier(Window owner, DeepSystemsContext ctx, WorldIndex index, EngineeringArchitecture a, EngineeringAnalysisRecord analysis) { string title = Prompt(owner, "ENGINEERING DOSSIER", "Decision dossier title", a.Name + " · configuration decision"); if (String.IsNullOrWhiteSpace(title)) return; string decision = PromptLarge(owner, "ENGINEERING DECISION", "Bounded decision, selected alternative and conditions", "Retain the current architecture as a bounded concept pending verification, risk retirement and authorized baseline."); if (decision == null) return; EngineeringConfigurationBaseline baseline = Store.Baselines.Where(x => Eq(x.ArchitectureId, a.Id)).OrderByDescending(x => x.FrozenUtc).FirstOrDefault(); EngineeringDecisionDossier d = new EngineeringDecisionDossier { Id = Id("dossier"), ArchitectureId = a.Id, AnalysisId = analysis.Id, BaselineId = baseline == null ? "" : baseline.Id, Title = Short(title, 240), Status = "DRAFT", CreatedUtc = Now(), UpdatedUtc = Now(), Decision = Short(decision, MaxLongText), EngineeringBoundary = "Decision is conditional on architecture fingerprint, explicit assumptions, unretired risks, analysis approximations and accepted verification evidence. It grants no build or deployment authority.", ArchitectureFingerprint = analysis.ArchitectureFingerprint, AnalysisCertificate = analysis.CertificateHash, Assumptions = new List<string>(a.Assumptions ?? new List<string>()), Risks = (a.FailureModes ?? new List<EngineeringFailureMode>()).OrderByDescending(x => x.RiskPriorityNumber).Take(64).Select(x => x.ToString()).ToList(), EvidenceNodeIds = new List<string>(a.EvidenceNodeIds ?? new List<string>()) }; Store.Dossiers.Insert(0, d); Save(ctx); AppendLedger(ctx, "DOSSIER_CREATED", d.Id, d.Title, d.ArchitectureFingerprint, d.AnalysisCertificate); OpenDossier(owner, ctx, index, d); }
