        private static void OpenDossier(Window owner, DeepSystemsContext ctx, WorldIndex index, EngineeringDecisionDossier d) { EngineeringArchitecture a = Architecture(d.ArchitectureId); bool drift = a == null || !Eq(SystemsEngineeringKernel.Fingerprint(a), d.ArchitectureFingerprint); Window w = W(owner, "YOMI · ENGINEERING DOSSIER · " + d.Title, 1220, 820); DockPanel root = Shell((d.Status ?? "DRAFT") + " · " + d.Title, (drift ? "ARCHITECTURE DRIFT · HISTORICAL BOUNDARY RETAINED" : "ARCHITECTURE FINGERPRINT CURRENT") + "\r\nanalysis " + d.AnalysisCertificate); WrapPanel tools = new WrapPanel(); foreach (string status in new[] { "DRAFT", "REVIEWING", "AUTHORIZED_FOR_DESIGN", "RETIRED" }) { string captured = status; tools.Children.Add(Btn(captured, delegate { d.Status = captured; d.UpdatedUtc = Now(); Save(ctx); AppendLedger(ctx, "DOSSIER_" + captured, d.Id, d.Title, d.ArchitectureFingerprint, d.AnalysisCertificate); })); } tools.Children.Add(Btn("ADD DISSENT", delegate { string text = PromptLarge(w, "ENGINEERING DISSENT", "Objection, unresolved trade or alternative", ""); if (!String.IsNullOrWhiteSpace(text)) { d.Dissent.Insert(0, Short(text, MaxLongText)); d.Dissent = d.Dissent.Take(256).ToList(); d.UpdatedUtc = Now(); Save(ctx); } })); DockPanel.SetDock(tools, Dock.Top); root.Children.Add(tools); root.Children.Add(ReadOnly("DECISION\r\n" + d.Decision + "\r\n\r\nENGINEERING BOUNDARY\r\n" + d.EngineeringBoundary + "\r\n\r\nRISKS\r\n" + String.Join("\r\n", d.Risks.Select(x => "  ! " + x).ToArray()) + "\r\n\r\nDISSENT\r\n" + String.Join("\r\n", d.Dissent.Select(x => "  × " + x).ToArray()))); root.Children.Add(EvidenceList(w, ctx, index, d.EvidenceNodeIds)); w.Content = root; w.Show(); }

