        private static EngineeringArchitecture LatestProjection(string kind, string id) { return Store.Architectures.Where(x => Eq(x.SourceKind, kind) && Eq(x.SourceId, id)).OrderByDescending(x => x.UpdatedUtc ?? x.CreatedUtc).FirstOrDefault(); }
        private static EngineeringArchitecture Architecture(string id) { return Store.Architectures.FirstOrDefault(x => Eq(x.Id, id)); }
        private static EngineeringArchitecture ChooseArchitecture(Window owner) { return ChooseObject(owner, "SELECT SYSTEM ARCHITECTURE", "Choose an active engineering boundary", Store.Architectures.Where(x => Active(x.Status)).OrderByDescending(x => x.UpdatedUtc ?? x.CreatedUtc).Cast<object>().ToList()) as EngineeringArchitecture; }
        private static string ComponentName(EngineeringArchitecture a, string id) { EngineeringComponent c = a == null ? null : a.Components.FirstOrDefault(x => Eq(x.Id, id)); return c == null ? id ?? "∅" : c.Name; }
        private static string InterfaceName(EngineeringArchitecture a, string id) { EngineeringInterface i = a == null ? null : a.Interfaces.FirstOrDefault(x => Eq(x.Id, id)); return i == null ? id ?? "∅" : i.Name; }
        private static void Touch(EngineeringArchitecture a) { a.Revision = Math.Max(1, a.Revision) + 1; a.UpdatedUtc = Now(); }

        private static void Load(DeepSystemsContext ctx) { lock (Gate) { if (Store != null && Eq(LoadedRoot, ctx.StateRoot)) return; LoadedRoot = ctx.StateRoot; Store = null; string path = StorePath(ctx); if (File.Exists(path)) try { Store = Json.Deserialize<DysonEngineeringStore>(File.ReadAllText(path, Encoding.UTF8)); } catch { PreserveCorrupt(path); } if (Store == null && File.Exists(path + ".previous")) try { Store = Json.Deserialize<DysonEngineeringStore>(File.ReadAllText(path + ".previous", Encoding.UTF8)); } catch { } if (Store == null) Store = new DysonEngineeringStore(); NormalizeStore(); } }
        private static void NormalizeStore() { if (Store == null) Store = new DysonEngineeringStore(); Store.Schema = 1; Store.Architectures = Store.Architectures ?? new List<EngineeringArchitecture>(); Store.Analyses = Store.Analyses ?? new List<EngineeringAnalysisRecord>(); Store.Baselines = Store.Baselines ?? new List<EngineeringConfigurationBaseline>(); Store.Changes = Store.Changes ?? new List<EngineeringChangeRecord>(); Store.Dossiers = Store.Dossiers ?? new List<EngineeringDecisionDossier>(); Store.RecentQuestions = Store.RecentQuestions ?? new List<string>(); foreach (EngineeringArchitecture a in Store.Architectures) { a.Requirements = (a.Requirements ?? new List<EngineeringRequirement>()).Take(MaxRequirements).ToList(); a.Components = (a.Components ?? new List<EngineeringComponent>()).Take(MaxComponents).ToList(); a.Interfaces = (a.Interfaces ?? new List<EngineeringInterface>()).Take(MaxInterfaces).ToList(); a.Budgets = (a.Budgets ?? new List<EngineeringResourceBudget>()).Take(MaxBudgets).ToList(); a.Tasks = (a.Tasks ?? new List<EngineeringTask>()).Take(MaxTasks).ToList(); a.FailureModes = (a.FailureModes ?? new List<EngineeringFailureMode>()).Take(MaxFailureModes).ToList(); a.FaultGates = (a.FaultGates ?? new List<EngineeringFaultGate>()).Take(MaxFaultGates).ToList(); a.Criteria = (a.Criteria ?? new List<EngineeringCriterion>()).Take(MaxCriteria).ToList(); a.Alternatives = (a.Alternatives ?? new List<EngineeringAlternative>()).Take(MaxAlternatives).ToList(); a.VerificationLinks = (a.VerificationLinks ?? new List<EngineeringVerificationLink>()).Take(MaxVerificationLinks).ToList(); a.SafetyClaims = (a.SafetyClaims ?? new List<EngineeringSafetyClaim>()).Take(MaxSafetyClaims).ToList(); a.Assumptions = a.Assumptions ?? new List<string>(); a.EvidenceNodeIds = (a.EvidenceNodeIds ?? new List<string>()).Take(MaxEvidence).ToList(); foreach (EngineeringRequirement q in a.Requirements) { q.SatisfiedByComponentIds = q.SatisfiedByComponentIds ?? new List<string>(); q.DerivedFromRequirementIds = q.DerivedFromRequirementIds ?? new List<string>(); q.EvidenceNodeIds = q.EvidenceNodeIds ?? new List<string>(); } foreach (EngineeringComponent c in a.Components) { c.Attributes = c.Attributes ?? new Dictionary<string, double>(StringComparer.OrdinalIgnoreCase); c.EvidenceNodeIds = c.EvidenceNodeIds ?? new List<string>(); } foreach (EngineeringInterface i in a.Interfaces) i.EvidenceNodeIds = i.EvidenceNodeIds ?? new List<string>(); foreach (EngineeringResourceBudget b in a.Budgets) b.Allocations = b.Allocations ?? new Dictionary<string, double>(StringComparer.OrdinalIgnoreCase); foreach (EngineeringTask t in a.Tasks) { t.PredecessorTaskIds = t.PredecessorTaskIds ?? new List<string>(); t.EvidenceNodeIds = t.EvidenceNodeIds ?? new List<string>(); } foreach (EngineeringFailureMode f in a.FailureModes) f.EvidenceNodeIds = f.EvidenceNodeIds ?? new List<string>(); foreach (EngineeringFaultGate g in a.FaultGates) g.InputIds = g.InputIds ?? new List<string>(); foreach (EngineeringAlternative x in a.Alternatives) { x.Metrics = x.Metrics ?? new Dictionary<string, double>(StringComparer.OrdinalIgnoreCase); x.SelectedComponentIds = x.SelectedComponentIds ?? new List<string>(); x.Assumptions = x.Assumptions ?? new List<string>(); } foreach (EngineeringVerificationLink v in a.VerificationLinks) v.EvidenceNodeIds = v.EvidenceNodeIds ?? new List<string>(); foreach (EngineeringSafetyClaim s in a.SafetyClaims) { s.EvidenceNodeIds = s.EvidenceNodeIds ?? new List<string>(); s.VerificationLinkIds = s.VerificationLinkIds ?? new List<string>(); } } foreach (EngineeringChangeRecord c in Store.Changes) { c.ImpactedComponentIds = c.ImpactedComponentIds ?? new List<string>(); c.ImpactedRequirementIds = c.ImpactedRequirementIds ?? new List<string>(); c.EvidenceNodeIds = c.EvidenceNodeIds ?? new List<string>(); } foreach (EngineeringDecisionDossier d in Store.Dossiers) { d.Assumptions = d.Assumptions ?? new List<string>(); d.Risks = d.Risks ?? new List<string>(); d.Dissent = d.Dissent ?? new List<string>(); d.EvidenceNodeIds = d.EvidenceNodeIds ?? new List<string>(); } }
        private static void TrimStore() { NormalizeStore(); Store.Architectures = Store.Architectures.Take(MaxArchitectures).ToList(); Store.Analyses = Store.Analyses.Take(MaxAnalyses).ToList(); Store.Baselines = Store.Baselines.Take(MaxBaselines).ToList(); Store.Changes = Store.Changes.Take(MaxChanges).ToList(); Store.Dossiers = Store.Dossiers.Take(MaxDossiers).ToList(); Store.RecentQuestions = Store.RecentQuestions.Take(192).ToList(); }
        private static void Save(DeepSystemsContext ctx) { lock (Gate) { TrimStore(); Store.Revision = Math.Max(0, Store.Revision) + 1; Store.UpdatedUtc = Now(); Store.LastCommitId = Id("engineering-commit"); string path = StorePath(ctx); Directory.CreateDirectory(Path.GetDirectoryName(path)); AtomicWrite(path, Json.Serialize(Store)); } }
        private static void AtomicWrite(string path, string text) { string temp = path + ".tmp." + Guid.NewGuid().ToString("N"); File.WriteAllText(temp, text ?? "", new UTF8Encoding(false)); if (File.Exists(path)) { string previous = path + ".previous"; try { File.Replace(temp, path, previous, true); return; } catch { try { File.Copy(path, previous, true); } catch { } } } if (File.Exists(path)) File.Delete(path); File.Move(temp, path); }
        private static void PreserveCorrupt(string path) { try { if (!File.Exists(path)) return; byte[] bytes = File.ReadAllBytes(path); string destination = path + ".corrupt." + HashBytes(bytes).Substring(0, 16) + ".json"; if (!File.Exists(destination)) File.Copy(path, destination); } catch { } }
        private static string StorePath(DeepSystemsContext ctx) { return Path.Combine(ctx.StateRoot, "controller-dyson-systems-engineering.json"); }
        private static string LedgerPath(DeepSystemsContext ctx) { return Path.Combine(ctx.StateRoot, "controller-dyson-systems-engineering-ledger.jsonl"); }
        private static void AppendLedger(DeepSystemsContext ctx, string evt, string subject, string detail, string fingerprint, string certificate) { lock (Gate) try { Directory.CreateDirectory(ctx.StateRoot); List<EngineeringLedgerRecord> prior = ReadLedger(ctx, 8192); EngineeringLedgerRecord last = prior.OrderByDescending(x => x.Sequence).FirstOrDefault(); EngineeringLedgerRecord r = new EngineeringLedgerRecord { Schema = 1, Sequence = last == null ? 1 : last.Sequence + 1, Utc = Now(), Event = Short(evt, 120), Subject = Short(subject, 512), Detail = Short(detail, MaxLongText), CorrelationId = Store == null ? "" : Store.LastCommitId, ArchitectureFingerprint = Short(fingerprint, 128), CertificateHash = Short(certificate, 128), PrevHash = last == null ? new string('0', 64) : last.EntryHash }; r.EntryHash = LedgerHash(r); byte[] bytes = Encoding.UTF8.GetBytes(Json.Serialize(r) + Environment.NewLine); using (FileStream stream = new FileStream(LedgerPath(ctx), FileMode.Append, FileAccess.Write, FileShare.Read, 4096, FileOptions.WriteThrough)) { stream.Write(bytes, 0, bytes.Length); stream.Flush(); } } catch { } }
        private static List<EngineeringLedgerRecord> ReadLedger(DeepSystemsContext ctx, int cap) { List<EngineeringLedgerRecord> rows = new List<EngineeringLedgerRecord>(); if (!File.Exists(LedgerPath(ctx))) return rows; try { foreach (string line in TakeLast(File.ReadLines(LedgerPath(ctx)).Where(x => !String.IsNullOrWhiteSpace(x)), cap)) try { EngineeringLedgerRecord row = Json.Deserialize<EngineeringLedgerRecord>(line); if (row != null) rows.Add(row); } catch { } } catch { } return rows; }
        private static string VerifyLedger(List<EngineeringLedgerRecord> rows) { if (rows == null || rows.Count == 0) return "EMPTY LEDGER"; rows = rows.OrderBy(x => x.Sequence).ToList(); long expected = rows[0].Sequence; string prior = rows[0].PrevHash; foreach (EngineeringLedgerRecord row in rows) { if (row.Sequence != expected) return "CHAIN GAP @ " + expected; if (!Eq(row.PrevHash, prior)) return "PREV HASH MISMATCH @ " + row.Sequence; if (!Eq(row.EntryHash, LedgerHash(row))) return "ENTRY HASH MISMATCH @ " + row.Sequence; expected++; prior = row.EntryHash; } return "CHAIN VERIFIED · " + rows.Count.ToString(CultureInfo.InvariantCulture) + " RECORDS"; }
        private static string LedgerHash(EngineeringLedgerRecord r) { return HashText(r.Schema + "|" + r.Sequence + "|" + (r.Utc ?? "") + "|" + (r.Event ?? "") + "|" + (r.Subject ?? "") + "|" + (r.Detail ?? "") + "|" + (r.CorrelationId ?? "") + "|" + (r.ArchitectureFingerprint ?? "") + "|" + (r.CertificateHash ?? "") + "|" + (r.PrevHash ?? "")); }

        private static void OpenRows(Window owner, string title, IList<object> rows, string subtitle) { Window w = W(owner, "YOMI · " + title, 1200, 800); DockPanel root = Shell(title, subtitle); ListBox list = List(); list.ItemsSource = rows ?? new List<object>(); root.Children.Add(list); w.Content = root; w.Show(); }
        private static int Score(string raw) { return (int)Math.Max(1, Math.Min(10, Number(raw, 1))); }
        private static bool Active(string status) { return !Eq(status, "ARCHIVED") && !Eq(status, "DISABLED") && !Eq(status, "RETIRED") && !Eq(status, "REJECTED"); }
        private static bool Eq(string a, string b) { return String.Equals(a ?? "", b ?? "", StringComparison.OrdinalIgnoreCase); }
        private static double Number(string raw, double fallback) { double value; return Double.TryParse(raw, NumberStyles.Float, CultureInfo.InvariantCulture, out value) && !Double.IsNaN(value) && !Double.IsInfinity(value) ? value : fallback; }
        private static List<string> Lines(string raw) { return (raw ?? "").Replace("\r", "").Split(new[] { '\n', ';' }, StringSplitOptions.RemoveEmptyEntries).Select(x => x.Trim()).Where(x => x.Length > 0).ToList(); }
        private static string Short(string value, int cap) { value = value ?? ""; cap = Math.Max(1, cap); return value.Length <= cap ? value : value.Substring(0, cap - 1) + "…"; }
        private static string HashText(string value) { return HashBytes(Encoding.UTF8.GetBytes(value ?? "")); }
        private static string HashBytes(byte[] value) { using (SHA256 hash = SHA256.Create()) return BitConverter.ToString(hash.ComputeHash(value ?? new byte[0])).Replace("-", "").ToLowerInvariant(); }
        private static string Id(string prefix) { return prefix + "-" + DateTime.UtcNow.ToString("yyyyMMddHHmmssfff", CultureInfo.InvariantCulture) + "-" + Guid.NewGuid().ToString("N").Substring(0, 8); }
        private static string Now() { return DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture); }
        private static IEnumerable<TValue> TakeLast<TValue>(IEnumerable<TValue> source, int count) { Queue<TValue> q = new Queue<TValue>(); foreach (TValue item in source ?? Enumerable.Empty<TValue>()) { q.Enqueue(item); if (q.Count > count) q.Dequeue(); } foreach (TValue item in q) yield return item; }
        private static ListBox EvidenceList(Window owner, DeepSystemsContext ctx, WorldIndex index, IEnumerable<string> ids) { ListBox list = List(); list.MaxHeight = 180; if (index != null) list.ItemsSource = (ids ?? Enumerable.Empty<string>()).Where(index.Nodes.ContainsKey).Select(x => index.Nodes[x]).ToList(); list.MouseDoubleClick += delegate { WorldNode n = list.SelectedItem as WorldNode; if (n != null) WorldKernel.ExternalOpenDossier(owner, ctx, index, n.Id); }; return list; }
        private static Window W(Window owner, string title, double width, double height) { return new Window { Title = title, Width = width, Height = height, MinWidth = Math.Min(width, 820), MinHeight = Math.Min(height, 560), Background = Bg, Foreground = Text, WindowStartupLocation = WindowStartupLocation.CenterOwner, Owner = owner, FontFamily = new FontFamily("Segoe UI") }; }
        private static DockPanel Shell(string title, string subtitle) { DockPanel root = new DockPanel { Margin = new Thickness(16) }; StackPanel head = new StackPanel { Margin = new Thickness(0, 0, 0, 10) }; head.Children.Add(T(title, 24, Text, FontWeights.Bold)); head.Children.Add(T(subtitle, 12, Muted, FontWeights.Normal)); DockPanel.SetDock(head, Dock.Top); root.Children.Add(head); return root; }
        private static TextBlock T(string value, double size, Brush foreground, FontWeight weight) { return new TextBlock { Text = value ?? "", FontSize = size, Foreground = foreground, FontWeight = weight, TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 2, 0, 2) }; }
        private static Button Btn(string label, RoutedEventHandler click) { Button button = new Button { Content = label, Margin = new Thickness(0, 0, 8, 8), Padding = new Thickness(12, 7, 12, 7), Background = Raised, Foreground = Text, BorderBrush = Border, BorderThickness = new Thickness(1), MinWidth = 112 }; if (click != null) button.Click += click; return button; }
        private static ListBox List() { return new ListBox { Background = Surface, Foreground = Text, BorderBrush = Border, BorderThickness = new Thickness(1), Margin = new Thickness(0, 6, 6, 0), Padding = new Thickness(5), FontFamily = new FontFamily("Cascadia Mono, Consolas") }; }
        private static TextBox ReadOnly(string value) { return new TextBox { Text = value ?? "", IsReadOnly = true, AcceptsReturn = true, TextWrapping = TextWrapping.Wrap, VerticalScrollBarVisibility = ScrollBarVisibility.Auto, HorizontalScrollBarVisibility = ScrollBarVisibility.Auto, Background = Surface, Foreground = Text, BorderBrush = Border, BorderThickness = new Thickness(1), Padding = new Thickness(10), Margin = new Thickness(0, 6, 6, 0), FontFamily = new FontFamily("Cascadia Mono, Consolas") }; }
        private static void Portal(Panel parent, string badge, string title, string description, Action open) { Button button = new Button { Width = 360, Height = 120, Margin = new Thickness(0, 0, 10, 10), Padding = new Thickness(12), Background = Surface, Foreground = Text, BorderBrush = Border, BorderThickness = new Thickness(1), HorizontalContentAlignment = HorizontalAlignment.Stretch }; StackPanel content = new StackPanel(); content.Children.Add(T(badge + "   " + title, 14, Accent, FontWeights.Bold)); content.Children.Add(T(description, 11.5, Muted, FontWeights.Normal)); button.Content = content; button.Click += delegate { if (open != null) open(); }; parent.Children.Add(button); }
        private static Brush B(string hex) { return new SolidColorBrush((Color)ColorConverter.ConvertFromString(hex)); }
        private static string Prompt(Window owner, string title, string label, string initial) { Window w = W(owner, "YOMI · " + title, 660, 280); DockPanel root = new DockPanel { Margin = new Thickness(16) }; TextBlock caption = T(label, 12, Muted, FontWeights.Normal); DockPanel.SetDock(caption, Dock.Top); root.Children.Add(caption); TextBox editor = new TextBox { Text = initial ?? "", MaxLength = MaxShortText, Margin = new Thickness(0, 8, 0, 10), Background = Surface, Foreground = Text, BorderBrush = Border, Padding = new Thickness(8) }; DockPanel.SetDock(editor, Dock.Top); root.Children.Add(editor); WrapPanel buttons = new WrapPanel { HorizontalAlignment = HorizontalAlignment.Right }; string result = null; buttons.Children.Add(Btn("OK", delegate { result = editor.Text; w.DialogResult = true; })); buttons.Children.Add(Btn("CANCEL", delegate { w.DialogResult = false; })); root.Children.Add(buttons); w.Content = root; bool? accepted = w.ShowDialog(); return accepted == true ? result : null; }
        private static string PromptLarge(Window owner, string title, string label, string initial) { Window w = W(owner, "YOMI · " + title, 780, 540); DockPanel root = new DockPanel { Margin = new Thickness(16) }; TextBlock caption = T(label, 12, Muted, FontWeights.Normal); DockPanel.SetDock(caption, Dock.Top); root.Children.Add(caption); TextBox editor = new TextBox { Text = initial ?? "", MaxLength = MaxLongText, AcceptsReturn = true, AcceptsTab = true, TextWrapping = TextWrapping.NoWrap, VerticalScrollBarVisibility = ScrollBarVisibility.Auto, HorizontalScrollBarVisibility = ScrollBarVisibility.Auto, Margin = new Thickness(0, 8, 0, 0), Background = Surface, Foreground = Text, BorderBrush = Border, Padding = new Thickness(10), FontFamily = new FontFamily("Cascadia Mono, Consolas") }; WrapPanel buttons = new WrapPanel { HorizontalAlignment = HorizontalAlignment.Right, Margin = new Thickness(0, 10, 0, 0) }; string result = null; buttons.Children.Add(Btn("SAVE", delegate { result = editor.Text; w.DialogResult = true; })); buttons.Children.Add(Btn("CANCEL", delegate { w.DialogResult = false; })); DockPanel.SetDock(buttons, Dock.Bottom); root.Children.Add(buttons); root.Children.Add(editor); w.Content = root; bool? accepted = w.ShowDialog(); return accepted == true ? result : null; }
        private static string Choose(Window owner, string title, string label, IEnumerable<string> choices, string preferred) { object selected = ChooseObject(owner, title, label, (choices ?? Enumerable.Empty<string>()).Cast<object>().ToList(), preferred); return selected == null ? null : Convert.ToString(selected, CultureInfo.InvariantCulture); }
        private static object ChooseObject(Window owner, string title, string label, IList<object> choices) { return ChooseObject(owner, title, label, choices, null); }
        private static object ChooseObject(Window owner, string title, string label, IList<object> choices, string preferred) { Window w = W(owner, "YOMI · " + title, 700, 470); DockPanel root = new DockPanel { Margin = new Thickness(16) }; TextBlock caption = T(label, 12, Muted, FontWeights.Normal); DockPanel.SetDock(caption, Dock.Top); root.Children.Add(caption); ListBox list = List(); list.ItemsSource = choices ?? new List<object>(); if (!String.IsNullOrWhiteSpace(preferred)) list.SelectedItem = list.Items.Cast<object>().FirstOrDefault(x => Eq(Convert.ToString(x, CultureInfo.InvariantCulture), preferred)); if (list.SelectedIndex < 0 && list.Items.Count > 0) list.SelectedIndex = 0; WrapPanel buttons = new WrapPanel { HorizontalAlignment = HorizontalAlignment.Right, Margin = new Thickness(0, 10, 0, 0) }; object result = null; buttons.Children.Add(Btn("SELECT", delegate { result = list.SelectedItem; w.DialogResult = true; })); buttons.Children.Add(Btn("CANCEL", delegate { w.DialogResult = false; })); list.MouseDoubleClick += delegate { result = list.SelectedItem; if (result != null) w.DialogResult = true; }; DockPanel.SetDock(buttons, Dock.Bottom); root.Children.Add(buttons); root.Children.Add(list); w.Content = root; bool? accepted = w.ShowDialog(); return accepted == true ? result : null; }
    }
}
